const m=(...p)=>R('Slides_04_Logical_DB_Design.pdf',p);
const Q=(difficulty,type,prompt,options,answer,explanation,hint,refs)=>({difficulty,type,prompt,options,answer,explanation,hint,refs});
const mc=(d,p,o,a,x,h,r)=>Q(d,'mc',p,o,a,x,h,r);
const tf=(d,p,a,x,h,r)=>Q(d,'tf',p,['Doğru','Yanlış'],a?0:1,x,h,r);
const sh=(d,p,a,x,h,r)=>Q(d,'short',p,[],Array.isArray(a)?a:[a],x,h,r);
const nu=(d,p,v,x,h,r)=>({...sh(d,p,String(v),x,h,r),numeric:{value:v,tolerance:0,units:[]},answerFormat:{kind:'number',tolerance:0,units:[]}});
const mu=(d,p,o,a,x,h,r)=>Q(d,'multi',p,o,a,x,h,r);
const ma=(d,p,o,a,x,h,r)=>Q(d,'match',p,o,a,x,h,r);
const or=(d,p,a,x,h,r)=>Q(d,'order',p,[...a],a,x,h,r);
const S=(title,text,example,diagram)=>({title,text,...(example?{example}:{}),...(diagram?{diagram}:{})});
const C=(prompt,options,answer,explanation)=>({prompt,options,answer,explanation});
const L=(title,summary,refs,sections,cards,checks)=>({title,summary,refs,sections,cards,checks});

